      expect(cd.isOk, isTrue, reason: cd.errorOrNull?.message);
      final cat = await session.exec('cat t.txt');
      expect(cat.isOk, isTrue, reason: cat.errorOrNull?.message);
      expect(rec.configs.single.args, ['cat', '/work/t.txt']);
    });

