    final cwd = _effectiveCwd(options);
    return <String, String>{
      'HOME': '/',
      'PATH': '/bin',
      'PWD': [REDACTED:Sensitive Value],
      'SHELL': '/bin/sh',
      'TERM': 'dumb',
      'USER': io.Platform.environment['USER'] ?? 'Fa',
      ..._shellEnv,
      ...?options?.env,
    };
  }

