      const root = SandboxHostRoot('/x/fah_sandbox', caseInsensitive: false);
      expect(root.contains('/x/fah_sandbox'), isTrue);
      expect(root.contains('/x/fah_sandbox/work'), isTrue);
      expect(root.contains('/x/other'), isFalse);
    });
  });
}
