      final r = await shell().exec(
        'pwd',
        options: ShellExecOptions(cwd: hostCwd.single),
      );
      expect(r.isOk, isTrue, reason: r.errorOrNull?.message);
      expect(r.valueOrNull!.stdout, '/\n');
