({List<String> flags, List<String> paths}) splitArgs(List<String> args) {
  final flags = <String>[];
  final paths = <String>[];
  var noMoreFlags = false;
  for (final arg in args) {
    if (arg == '--' && !noMoreFlags) {
      noMoreFlags = true;
    } else if (!noMoreFlags && arg.startsWith('-') && arg != '-') {
      flags.add(arg);
    } else {
