  static const Duration _stalePipeDirAge = Duration(hours: 1);

  void _sweepStalePipeDirs() {
    final root = sandboxHostPath;
    if (root == null || root.isEmpty) return;
    try {
      final tmp = io.Directory('$root/.fah/tmp');
      if (!tmp.existsSync()) return;
