    // SandboxedExecutionEnv._map, a sandbox-virtual path that textually
    // begins with the host root is treated as already mapped; both
    // readings stay inside the sandbox.
    if (host.isNotEmpty &&
        (sandboxPath == host || sandboxPath.startsWith('$host/'))) {
