      expect(init.valueOrNull!.exitCode, 0, reason: init.valueOrNull!.stderr);
      expect(io.Directory('${sandbox.path}/.git').existsSync(), isTrue);
      expect(io.Directory('${sandbox.path}/var').existsSync(), isFalse);
